function legalPage(kind){
 const pages={privacy:['Privacy Policy','How HireeBridge collects, uses and protects student information.',['We collect information needed to provide enrollment and credential services, such as name, email, selected domain, duration and payment reference.','Payment card data should be handled by the payment provider rather than stored directly by HireeBridge.','We may use information to deliver certificates, provide support, prevent abuse and maintain transaction records.','We do not publish student information as a testimonial without appropriate consent.','You can contact support at '+SUPPORT_EMAIL+' about privacy requests.']],terms:['Terms of Service','Rules for using HireeBridge internship and credential services.',['HireeBridge provides internship program workflows and credential-related services described at checkout.','A certificate must represent a program or credential actually purchased and completed according to its stated conditions.','Students are responsible for providing accurate information and using credentials honestly.','Program availability, domain content and delivery timelines can change; the applicable checkout terms control the purchase.','Nothing on the site guarantees employment, admission, salary or a specific academic outcome.']],refund:['Refund Policy','Refund and cancellation terms for HireeBridge purchases.',['Review the product description before payment and retain your receipt.','If a paid service has not started or the applicable eligibility condition allows cancellation, contact '+SUPPORT_EMAIL+' with the order details.','Once a certificate has been generated or a digital service has been substantially delivered, refund eligibility may be limited by the nature of the service and applicable law.','Payment-provider fees, taxes or third-party costs may affect the amount returned where permitted.','The final production policy should be reviewed by qualified counsel for the jurisdictions where the service is sold.']],about:['About HireeBridge','A student-first internship workflow connecting structured programs with credential delivery.',['HireeBridge is designed around a simple idea: students should know what they are buying, what they need to complete and what document they will receive.','The platform supports domains across technology, data, cloud, design, product and analytics.','GreyRocks is presented as the credential issuer in the current certificate workflow.','The platform does not promise employment or academic acceptance; students should confirm requirements with the relevant institution.','Support: '+SUPPORT_EMAIL+'.']],contact:['Contact HireeBridge','Questions about programs, payments or credential delivery?',['Email: '+SUPPORT_EMAIL,'For production launch, connect a monitored support mailbox and publish business address details required by applicable law.','For credential verification, use the GreyRocks verification destination shown on the certificate.','For payment issues, include your order/reference number so support can locate the transaction.','Typical support topics include domain selection, order status, certificate download and refund questions.']]};
 const p=pages[kind]||pages.privacy; return layout({title:`${p[0]} | HireeBridge`,description:p[1],active:`/${kind}`,content:`<main><section class="page-hero"><div class="eyebrow">${esc(p[0])}</div><h1>${esc(p[0])}</h1><p>${esc(p[1])}</p></section><section class="section legal"><div class="legal-card">${p[2].map((x,i)=>`<h2>${i+1}. ${['Scope','Data and information','Use of information','Accuracy and responsible use','Contact'][i]||'Additional information'}</h2><p>${esc(x)}</p>`).join('')}</div></section>${faq([['Where can I ask questions?','Email '+SUPPORT_EMAIL+'.'],['Do you store payment card details?','The production architecture should use the payment provider for card handling and store only necessary transaction references.'],['Can policies change?','Yes. The current policy shown at the time of purchase should be retained with the transaction record.'],['Are job outcomes guaranteed?','No. HireeBridge does not guarantee employment, salary, admission or a specific career outcome.'],['Who issues the credential?','GreyRocks is the stated credential issuer in the current workflow.']])}</main>`});
}

