function generateCredentialId(domain){return `GR-${domain.split(/\s+/).map(x=>x[0]).join('').slice(0,4).toUpperCase()}-${new Date().getFullYear()}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;}
async function createCertificate({name,domain,duration,issueDate,credentialId}){
 const qrData = await QRCode.toDataURL(`${GREYROCKS_URL.replace(/\/$/,'')}/verification/${encodeURIComponent(credentialId)}`,{margin:1,width:300,color:{dark:'#0B1F36',light:'#FFFFFF'}});
 const qrBuffer=Buffer.from(qrData.split(',')[1],'base64');
 const pdfDoc=await PDFDocument.create();
 const page=pdfDoc.addPage([842,595]);
 const bgBytes=await fs.promises.readFile(TEMPLATE);
 const bg=await pdfDoc.embedJpg(bgBytes);
 page.drawImage(bg,{x:0,y:0,width:842,height:595});
 const navy={color:undefined};
 const font=await pdfDoc.embedFont('Helvetica');
 const bold=await pdfDoc.embedFont('Times-Bold');
 const scaleX=842/2048, scaleY=595/1448;
 function center(text,xPx,yPx,size,fontObj){const w=fontObj.widthOfTextAtSize(text,size);page.drawText(text,{x:xPx*scaleX-w/2,y:595-yPx*scaleY-size*scaleY,font:fontObj,size:size*scaleY,color:{type:undefined}})}
 // pdf-lib colors use rgb; kept local to avoid coupling the web palette.
 const { rgb } = require('pdf-lib');
 const ink=rgb(11/255,31/255,54/255);
 const valueSize=10*scaleY;
 const nameSize=30*scaleY;
 const drawCentered=(text,xPx,yPx,size,fontObj)=>{const w=fontObj.widthOfTextAtSize(text,size);page.drawText(text,{x:xPx*scaleX-w/2,y:595-yPx*scaleY-size,font:fontObj,size,color:ink});};
 drawCentered(name,1024,640,30*scaleY,bold);
 const fields=[[duration,345],[domain,590],[issueDate,820],[credentialId,1115]];
 for(const [text,x] of fields) drawCentered(String(text),x,746,10*scaleY,font);
 const qr=await pdfDoc.embedPng(qrBuffer); page.drawImage(qr,{x:1340*scaleX,y:595-(1080+170)*scaleY,width:170*scaleX,height:170*scaleY});
 const pdf=await pdfDoc.save();
 const pdfFile=path.join(GENERATED,`${credentialId}.pdf`); await fs.promises.writeFile(pdfFile,pdf);
 const svgFile=path.join(GENERATED,`${credentialId}.svg`);
 const bg64=bgBytes.toString('base64');
 const qrSvg=await QRCode.toString(`${GREYROCKS_URL.replace(/\/$/,'')}/verification/${encodeURIComponent(credentialId)}`,{type:'svg',margin:1,width:170,color:{dark:'#0B1F36',light:'#FFFFFF'}});
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="2048" height="1448" viewBox="0 0 2048 1448"><image href="data:image/jpeg;base64,${bg64}" width="2048" height="1448"/><text x="1024" y="590" text-anchor="middle" font-family="Georgia,serif" font-size="58" font-weight="700" fill="#0B1F36">${esc(name)}</text><text x="345" y="746" text-anchor="middle" font-family="Arial" font-size="26" font-weight="700" fill="#0B1F36">${esc(duration)}</text><text x="590" y="746" text-anchor="middle" font-family="Arial" font-size="26" font-weight="700" fill="#0B1F36">${esc(domain)}</text><text x="820" y="746" text-anchor="middle" font-family="Arial" font-size="26" font-weight="700" fill="#0B1F36">${esc(issueDate)}</text><text x="1115" y="746" text-anchor="middle" font-family="Arial" font-size="26" font-weight="700" fill="#0B1F36">${esc(credentialId)}</text><g transform="translate(1340 1080)">${qrSvg.replace(/^<\?xml[^>]*>/,'').replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</g></svg>`;
 await fs.promises.writeFile(svgFile,svg);
 return {pdf:`/downloads/${credentialId}.pdf`,svg:`/downloads/${credentialId}.svg`};
}

function razorpayRequest(method, apiPath, body){
 return new Promise((resolve,reject)=>{
  const auth=Buffer.from(`${process.env.RAZORPAY_KEY_ID}:${process.env.RAZORPAY_KEY_SECRET}`).toString('base64');
  const data=body?JSON.stringify(body):'';
  const req=https.request({hostname:'api.razorpay.com',path:apiPath,method,headers:{Authorization:`Basic ${auth}`,'Content-Type':'application/json','Content-Length':Buffer.byteLength(data)}},res=>{let raw='';res.on('data',c=>raw+=c);res.on('end',()=>{let parsed;try{parsed=JSON.parse(raw)}catch{parsed={raw}};if(res.statusCode>=200&&res.statusCode<300)resolve(parsed);else reject(new Error(parsed.error?.description||'Razorpay request failed'));});});req.on('error',reject);if(data)req.write(data);req.end();
 });
}
async function sendMail(to,subject,text){
 if(!process.env.SMTP_HOST || !process.env.SMTP_USER) return {sent:false,reason:'SMTP not configured'};
 const d=db(); const today=new Date().toISOString().slice(0,10); const sentToday=d.orders.filter(o=>o.emailSentDate===today&&o.emailSent).length; const limit=Number(process.env.EMAIL_DAILY_LIMIT||300); if(sentToday>=limit)return {sent:false,reason:'daily limit'};
 const transporter=nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:Number(process.env.SMTP_PORT||587)===465,auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}});
 await transporter.sendMail({from:process.env.SMTP_USER,to,subject,text}); return {sent:true};
}

