app.post('/api/checkout',async(req,res)=>{
 const {name,email,domain,duration,plan,country,phone}=req.body||{};
 if(!name||!email||!domain||!duration||!plan)return res.status(400).json({error:'Missing required fields'});
 const chosen=plan==='direct'?'direct':'starter'; const domainName=domains.find(d=>d[1]===domain)?.[0]||domain;
 const data=db(); const orderId=`HB-${Date.now()}-${crypto.randomBytes(2).toString('hex').toUpperCase()}`;
 const order={id:orderId,name,email,domain:domainName,duration,plan:chosen,country:country||'',phone:phone||'',amount:plans[chosen].price,status:'created',createdAt:new Date().toISOString(),emailSent:false};
 if(process.env.RAZORPAY_KEY_ID && process.env.RAZORPAY_KEY_SECRET){
  try{const rp=await razorpayRequest('POST','/v1/orders',{amount:plans[chosen].price*100,currency:'INR',receipt:orderId,notes:{hireebridge_order:orderId,domain:domainName,plan:chosen}});order.gatewayOrderId=rp.id;data.orders.push(order);save(data);return res.json({ok:true,mode:'razorpay',orderId,gatewayOrderId:rp.id,keyId:process.env.RAZORPAY_KEY_ID,amount:plans[chosen].price*100,currency:'INR',name,email,description:plans[chosen].name});}catch(e){return res.status(502).json({error:e.message});}
 }
 // Local demo mode when payment credentials are intentionally blank.
 order.status='demo-paid';
 if(chosen==='direct'){
  const credentialId=generateCredentialId(domainName); const issueDate=formatDate(); const files=await createCertificate({name,domain:domainName,duration,issueDate,credentialId}); const cert={credentialId,orderId,name,email,domain:domainName,duration,issueDate,status:'issued',createdAt:new Date().toISOString(),...files}; data.certificates.push(cert); order.credentialId=credentialId;
  const mail=await sendMail(email,'Your HireeBridge credential is ready',`Your GreyRocks credential ${credentialId} is ready. PDF: ${SITE_URL}${files.pdf}`); order.emailSent=mail.sent; order.emailSentDate=mail.sent?new Date().toISOString().slice(0,10):null;
 } else { order.tasks=[{title:'Read your internship brief',done:false},{title:'Create or update your project repository',done:false},{title:'Push your project evidence to GitHub',done:false},{title:'Add the internship to your LinkedIn profile accurately',done:false},{title:'Submit completion evidence',done:false}]; }
 data.orders.push(order); save(data); res.json({ok:true,mode:'demo',orderId,plan:chosen,credentialId:order.credentialId||null,files:order.credentialId?data.certificates.find(c=>c.credentialId===order.credentialId):null,message:'Local demo payment confirmed. Configure Razorpay before production launch.'});
});

app.post('/api/payment/verify',async(req,res)=>{
 const {orderId,gatewayOrderId,paymentId,signature}=req.body||{};
 if(!orderId||!gatewayOrderId||!paymentId||!signature)return res.status(400).json({error:'Missing payment verification fields'});
 if(!process.env.RAZORPAY_KEY_SECRET)return res.status(400).json({error:'Razorpay is not configured'});
 const expected=crypto.createHmac('sha256',process.env.RAZORPAY_KEY_SECRET).update(`${gatewayOrderId}|${paymentId}`).digest('hex');
 if(!crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(signature)))return res.status(400).json({error:'Invalid payment signature'});
 const data=db(); const order=data.orders.find(o=>o.id===orderId); if(!order)return res.status(404).json({error:'Order not found'}); order.status='paid'; order.paymentId=paymentId; order.paidAt=new Date().toISOString();
 if(order.plan==='direct'&&!order.credentialId){const credentialId=generateCredentialId(order.domain);const issueDate=formatDate();const files=await createCertificate({name:order.name,domain:order.domain,duration:order.duration,issueDate,credentialId});const cert={credentialId,orderId:order.id,name:order.name,email:order.email,domain:order.domain,duration:order.duration,issueDate,status:'issued',createdAt:new Date().toISOString(),...files};data.certificates.push(cert);order.credentialId=credentialId;const mail=await sendMail(order.email,'Your HireeBridge credential is ready',`Your GreyRocks credential ${credentialId} is ready. PDF: ${SITE_URL}${files.pdf}`);order.emailSent=mail.sent;order.emailSentDate=mail.sent?new Date().toISOString().slice(0,10):null;}else if(order.plan==='starter'&&!order.tasks){order.tasks=[{title:'Read your internship brief',done:false},{title:'Create or update your project repository',done:false},{title:'Push your project evidence to GitHub',done:false},{title:'Add the internship to your LinkedIn profile accurately',done:false},{title:'Submit completion evidence',done:false}];}
 save(data); const cert=order.credentialId?data.certificates.find(c=>c.credentialId===order.credentialId):null; res.json({ok:true,order,certificate:cert});
});

