app.get('/blog/:slug',(req,res)=>{const p=blogPage(req.params.slug);if(!p)return res.status(404).send(layout({title:'Not found',description:'Page not found',content:'<main><section class="page-hero"><h1>Article not found</h1><a class="btn btn-dark" href="/blog">Back to blog</a></section></main>'}));res.send(p)});
for(const p of ['privacy','terms','refund','about','contact'])app.get('/'+p,(req,res)=>res.send(legalPage(p)));
app.get('*',(req,res)=>res.status(404).send(layout({title:'Page not found',description:'HireeBridge page not found',content:'<main><section class="page-hero"><div class="eyebrow">404</div><h1>This page is not here.</h1><p>Use the navigation to continue.</p><a class="btn btn-dark" href="/">Back home</a></section></main>'})));

app.listen(PORT,()=>console.log(`HireeBridge running at ${SITE_URL}`));
